import{AGUA_ACTIVA as l}from"../sim/agua.js?v=23d4ed5";import{TRONCOS_ACTIVOS as d}from"../sim/tronco.js?v=23d4ed5";const e=(t,n)=>({es:t,en:n}),a=(t,n=t)=>({es:t,en:n}),o=(t,n,r,s,i)=>({id:`mundo/${t}`,seccion:"mundo",icono:n,contenido:r,datos:s,relacionadas:i}),c=[o("clima","hoja",{es:{titulo:"El clima",subtitulo:"Estaciones y d\xEDa y noche, dos relojes engranados",resumen:"Un a\xF1o de cuatro estaciones \u2014una semana de juego cada una\u2014 y un ciclo de luz con amanecer y atardecer. Cambian el ritmo del mundo: cu\xE1nto brota, qu\xE9 fauna sale y cu\xE1nto castiga estar fuera.",bloques:[{titulo:"Estaciones",texto:"La primavera dobla los brotes de comida y el invierno los deja en un tercio. Las transiciones son suaves: el deshielo se ve venir, y el \xFAltimo tramo de cada estaci\xF3n ya vira hacia la siguiente."},{titulo:"D\xEDa y noche",texto:"La luz baja con rampas de atardecer y amanecer. De noche se ve menos lejos, los insectos se esconden y salen amenazas que no se ven. Los d\xEDas de verano son m\xE1s largos que los de invierno, y CU\xC1NTO m\xE1s lo decide el sitio: en el ecuador no cambia nada y cerca del c\xEDrculo polar el invierno se queda en cinco horas y media de luz."},{titulo:"La temperatura",texto:"Sube y baja con la estaci\xF3n y con la hora, con la inercia del suelo: el fr\xEDo aprieta despu\xE9s de anochecer y el m\xEDnimo llega de madrugada. El term\xF3metro de la barra la marca en grados, y el campo suena con ella: b\xFAho y grillos en la noche templada, chicharras cuando aprieta el verano y viento helado cuando baja de seis grados."}],consejo:"Elige el comienzo en el di\xE1logo de partida: el est\xE1ndar arranca en primavera y de d\xEDa \u2014 la temporada de acopio antes del primer invierno.",palabras:["estaciones","noche","temperatura","luz","clima","sonido","ambiente"]},en:{titulo:"The weather",subtitulo:"Seasons and day-night, two geared clocks",resumen:"A year of four seasons \u2014 a week of play each \u2014 and a light cycle with dawn and dusk. They set the world\u2019s rhythm: how much food sprouts, which wildlife shows up and how much it costs to stay outside.",bloques:[{titulo:"Seasons",texto:"Spring doubles food sprouts and winter cuts them to a third. Transitions are smooth: the thaw can be seen coming, and the last stretch of each season already leans into the next."},{titulo:"Day and night",texto:"Light fades with dusk and dawn ramps. At night you see less far, insects hide and unseen threats come out. Summer days are longer than winter ones, and HOW MUCH longer is decided by the place: on the equator nothing changes, and near the polar circle winter is down to five and a half hours of light."},{titulo:"Temperature",texto:"It rises and falls with the season and the hour, with the ground\u2019s inertia: cold bites after nightfall and bottoms out before dawn. The top-bar thermometer shows it in degrees, and the field sounds along with it: owl and crickets on a warm night, cicadas when summer bites, and freezing wind once it drops below six degrees."}],consejo:"Pick the start in the match dialog: the standard opens in spring at daytime \u2014 the stockpiling season before the first winter.",palabras:["seasons","night","temperature","light","weather","sound","ambience"]}},null,["mundo/sitio","mundo/noche","mundo/invierno"]),o("sitio","idioma",{es:{titulo:"El sitio",subtitulo:"D\xF3nde juegas decide el a\xF1o que te toca",resumen:"Cada escenario es un lugar del mundo, con su clima y su latitud. No se eligen por separado: eliges el sitio y el sitio los trae. De ah\xED salen el fr\xEDo, el calor y \u2014lo que casi nadie mira\u2014 cu\xE1ntas horas de luz tiene el d\xEDa en cada estaci\xF3n.",bloques:[{titulo:"Siete climas",texto:"El mediterr\xE1neo es el de siempre. El OCE\xC1NICO apenas hiela y tiene el a\xF1o m\xE1s suave; el CONTINENTAL hiela tambi\xE9n de d\xEDa en invierno y achicharra en verano. El DES\xC9RTICO no destaca por el calor sino por el salto entre el mediod\xEDa y el amanecer, veinte grados, y por eso hiela de noche aunque el d\xEDa haya sido templado. El TROPICAL es c\xE1lido todo el a\xF1o y no hiela nunca. El ECUATORIAL directamente no tiene a\xF1o: las cuatro estaciones se parecen. Y la ALTA MONTA\xD1A tiene el invierno m\xE1s duro de todos \u2014cinco bajo cero de d\xEDa y de noche\u2014 con un verano corto pero de verdad: es el \xFAnico sitio donde el a\xF1o entero se juega a llegar al buen tiempo con la colonia en pie."},{titulo:"La latitud manda en la luz",texto:"Cuanto m\xE1s lejos del ecuador, m\xE1s se separan el verano y el invierno. En el Amazonas el d\xEDa dura doce horas los trescientos sesenta y cinco d\xEDas; en el fiordo va de cinco horas y media en pleno invierno a dieciocho y media en pleno verano. Eso cambia la partida entera: cu\xE1nto rato se puede forrajear, cu\xE1nta noche hay que aguantar y cu\xE1ntas horas caza la ara\xF1a."},{titulo:"La altura enfr\xEDa",texto:"Cada mil metros quitan seis grados y medio, igual que en el mundo real. Por eso la sabana, a novecientos metros, juega seis grados por debajo de lo que su tr\xF3pico promete \u2014y aun as\xED no hiela\u2014, y la pradera, a quinientos, hiela de madrugada tres estaciones de cuatro. Ni el clima, ni la altitud, ni la latitud se tocan en ning\xFAn di\xE1logo: son lo que ES ese lugar, y la \xFAnica forma de cambiarlos es irte a otro sitio."}],consejo:"Mira la ficha del sitio en el di\xE1logo de partida \u2014el bot\xF3n de ayuda al lado del desplegable\u2014 antes de elegir. El desplegable los agrupa por continente: Europa, \xC1frica, Am\xE9rica, Asia y Ocean\xEDa. Un fiordo y un Amazonas se juegan tan distinto como dos especies.",palabras:["sitio","escenario","clima","latitud","altitud","lugar","mapa","oasis","taiga","fiordo","continente"]},en:{titulo:"The place",subtitulo:"Where you play decides the year you get",resumen:"Every scenario is a spot on the globe, with its own climate and latitude. You do not pick them separately: you pick the place and the place brings them. That is where the cold, the heat and \u2014 what almost nobody looks at \u2014 the hours of daylight in each season come from.",bloques:[{titulo:"Seven climates",texto:"The Mediterranean one is the old default. The OCEANIC barely freezes and has the mildest year; the CONTINENTAL freezes by day in winter and scorches in summer. The DESERT stands out not for its heat but for the twenty-degree gap between noon and dawn, which is why it freezes at night after a mild day. The TROPICAL is warm all year and never freezes. The EQUATORIAL has no year at all: its four seasons look alike. And the HIGH MOUNTAIN has the harshest winter of all \u2014five below zero day and night\u2014 with a short but genuine summer: it is the one place where the whole year is a race to reach the good weather with your colony still standing."},{titulo:"Latitude rules the light",texto:"The further from the equator, the wider summer and winter drift apart. In the Amazon the day lasts twelve hours all three hundred and sixty-five of them; in the fjord it runs from five and a half hours at midwinter to eighteen and a half at midsummer. That changes the whole match: how long you can forage, how much night you must sit through and how many hours the spider hunts."},{titulo:"Height cools",texto:"Every thousand metres take six and a half degrees off, exactly as in the real world. That is why the savannah, at nine hundred metres, plays six degrees below what its tropics promise \u2014 and still never freezes \u2014 while the prairie, at five hundred, frosts before dawn three seasons out of four. Climate, height and latitude are touched in no dialog at all: they are what that place IS, and the only way to change them is to go somewhere else."}],consejo:"Read the place card in the match dialog \u2014 the help button next to the dropdown \u2014 before you choose. The dropdown groups them by continent: Europe, Africa, America, Asia and Oceania. A fjord and an Amazon play as differently as two species.",palabras:["place","scenario","climate","latitude","altitude","location","map","oasis","taiga","fjord","continent"]}},[{etiqueta:e("Sitios","Places"),valor:a("Once, del outback al Caribe, en cinco continentes","Eleven, from the outback to the Caribbean, on five continents")},{etiqueta:e("Climas","Climates"),valor:a("Siete, y los siete en uso","Seven, all seven in use")},{etiqueta:e("El d\xEDa m\xE1s largo","Longest day"),valor:a("18,5 h en el fiordo","18.5 h in the fjord")},{etiqueta:e("El m\xE1s corto","Shortest"),valor:a("5,5 h, el mismo sitio en invierno","5.5 h, same place in winter")},{etiqueta:e("Sin estaciones","No seasons"),valor:a("Amazonas: 12 h todo el a\xF1o","Amazon: 12 h all year")}],["mundo/clima","mundo/invierno","mundo/noche"]),o("mediterraneo","idioma",{es:{titulo:"El Mediterr\xE1neo",subtitulo:"La costa de siempre: verano seco, invierno suave",resumen:"El sitio por defecto. Una costa del Tirreno a 38\xB0 norte y 30 metros sobre el mar, con el clima mediterr\xE1neo de toda la vida: verano seco y caluroso, invierno suave con alguna madrugada de escarcha. Pedregal de costa en piedras de dos y la comida en corros redondos, como olivos y pinos sueltos.",bloques:[{titulo:"El a\xF1o",texto:"Primavera a 17 grados de d\xEDa y 7 de madrugada; verano a 31 con noches de 21; oto\xF1o a 15 y 5; invierno a 1 grado al mediod\xEDa y madrugadas bajo cero. Hay dos estaciones enteras sin helada ni de d\xEDa ni de noche \u2014primavera y verano\u2014 y el oto\xF1o se queda a un pelo: es el sitio m\xE1s equilibrado del cat\xE1logo, y por eso es el que sale al abrir el juego."},{titulo:"El suelo",texto:"Roca al 10 por ciento en domin\xF3s \u2014un pedregal de costa, ni raso ni cerrado\u2014 y la flora en manchas redondas regulares, cada una un pozo de comida sin halo alrededor. Hay que encontrarlas y qued\xE1rselas: entre dos corros el suelo est\xE1 limpio."},{titulo:"La luz y la noche",texto:"El d\xEDa va de 9,4 horas en pleno invierno a 14,6 en pleno verano. De noche caza la ara\xF1a de siempre; la errante no llega hasta aqu\xED."}],consejo:"Es el sitio para aprender: nada aprieta demasiado. Aprovecha la primavera para levantar el segundo hormiguero al lado de un corro de flora y ten la despensa llena antes del invierno, que corto pero hiela.",palabras:["mediterr\xE1neo","mediterraneo","costa","olivos","pinos","sitio","europa","por defecto"]},en:{titulo:"The Mediterranean",subtitulo:"The familiar coast: dry summer, mild winter",resumen:"The default place. A Tyrrhenian coast at 38\xB0 north and 30 metres above the sea, with the Mediterranean climate the game was built on: a dry, hot summer and a mild winter with the odd frosty dawn. Coastal scree in pairs of stones, and food in regular round patches, like scattered olive trees and pines.",bloques:[{titulo:"The year",texto:"Spring at 17 degrees by day and 7 before dawn; summer at 31 with nights of 21; autumn at 15 and 5; winter at 1 degree at noon with dawns below zero. Two whole seasons \u2014 spring and summer \u2014 never freeze day or night, and autumn misses it by a hair: it is the most balanced place in the catalogue, which is why it is the one the game opens on."},{titulo:"The ground",texto:"Rock at 10 percent in dominoes \u2014 a coastal scree, neither bare nor closed \u2014 and flora in regular round patches, each one a well of food with no halo around it. You have to find them and hold them: between two patches the ground is clean."},{titulo:"Light and night",texto:"The day runs from 9.4 hours at midwinter to 14.6 at midsummer. At night the usual spider hunts; the wandering one does not reach this far."}],consejo:"This is the place to learn: nothing squeezes too hard. Use spring to raise the second anthill next to a patch of flora, and have the larder full before winter, which is short but does freeze.",palabras:["mediterranean","coast","olive","pine","place","europe","default"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Europa \xB7 38\xB0 norte \xB7 30 m","Europe \xB7 38\xB0 north \xB7 30 m")},{etiqueta:e("Clima","Climate"),valor:a("Mediterr\xE1neo","Mediterranean")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("31 \xB0C de d\xEDa \xB7 1 \xB0C de d\xEDa y \u22125 de madrugada","31 \xB0C by day \xB7 1 \xB0C by day and \u22125 before dawn")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 9,4 a 14,6 h","From 9.4 to 14.6 h")},{etiqueta:e("Roca","Rock"),valor:a("10 %, en domin\xF3s","10 %, in dominoes")},{etiqueta:e("Flora","Flora"),valor:a("0,7\xD7, corros redondos de radio 3,4","0.7\xD7, round patches of radius 3.4")},{etiqueta:e("De noche","At night"),valor:a("La ara\xF1a","The spider")}],["mundo/sitio","mundo/clima","mundo/invierno"]),o("pradera","idioma",{es:{titulo:"La Pradera",subtitulo:"Las Grandes Llanuras: abierta, y con un invierno de verdad",resumen:"Norteam\xE9rica, 41\xB0 norte y 500 metros de altura en el interior del continente. Clima continental: el verano achicharra y el invierno hiela tambi\xE9n al mediod\xEDa. Es el sitio con menos roca del cat\xE1logo \u2014casi todo es suelo\u2014 y la hierba crece en corros redondos grandes.",bloques:[{titulo:"El a\xF1o",texto:"Primavera a 14 grados de d\xEDa pero cuatro bajo cero de madrugada; verano a 34 con noches de 16; oto\xF1o a 11 y madrugadas heladas; invierno a cinco bajo cero de d\xEDa y de noche. Solo el verano est\xE1 libre de escarcha, as\xED que el a\xF1o se juega a llegar a \xE9l con la colonia entera y a llenar la despensa antes de que se acabe."},{titulo:"El suelo",texto:"Roca al 4 por ciento en piedra suelta: se camina recto a cualquier parte y se ve venir a todo el mundo. La comida crece en manchas redondas regulares, m\xE1s grandes que los olivos del Mediterr\xE1neo, y entre ellas el suelo est\xE1 raso. Sin muros donde parapetarse, quien llega antes al corro de al lado gana."},{titulo:"La luz y la noche",texto:"El d\xEDa va de 9 horas en pleno invierno a 15 en pleno verano: el verano da mucho rato para forrajear y el invierno casi nada. De noche caza la ara\xF1a de siempre."}],consejo:"Con tan poca roca la carrera es por los corros de hierba, no por los pasos. Expande en verano, cuando la noche no hiela, y no dejes columnas fuera al caer el oto\xF1o: la madrugada ya escarcha.",palabras:["pradera","llanura","continental","hierba","sitio","am\xE9rica","norteam\xE9rica"]},en:{titulo:"The Prairie",subtitulo:"The Great Plains: open, with a real winter",resumen:"North America, 41\xB0 north and 500 metres up in the middle of the continent. Continental climate: summer scorches and winter freezes even at noon. It is the place with the least rock in the catalogue \u2014 almost all of it is ground \u2014 and the grass grows in big round patches.",bloques:[{titulo:"The year",texto:"Spring at 14 degrees by day but four below zero before dawn; summer at 34 with nights of 16; autumn at 11 with frosty dawns; winter at five below by day and by night. Only summer is free of frost, so the year is a race to reach it with the whole colony and to fill the larder before it ends."},{titulo:"The ground",texto:"Rock at 4 percent as loose stones: you walk straight to anywhere and see everyone coming. Food grows in regular round patches, larger than the Mediterranean olive groves, and between them the ground is bare. With no walls to hide behind, whoever reaches the next patch first wins it."},{titulo:"Light and night",texto:"The day runs from 9 hours at midwinter to 15 at midsummer: summer gives plenty of foraging time and winter almost none. At night the usual spider hunts."}],consejo:"With so little rock the race is for the grass patches, not for the passes. Expand in summer, when the night does not freeze, and leave no columns outside when autumn falls: the dawns already frost.",palabras:["prairie","plains","continental","grass","place","america","north america"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Am\xE9rica \xB7 41\xB0 norte \xB7 500 m","America \xB7 41\xB0 north \xB7 500 m")},{etiqueta:e("Clima","Climate"),valor:a("Continental","Continental")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("34 \xB0C de d\xEDa \xB7 \u22125 \xB0C de d\xEDa y de noche","34 \xB0C by day \xB7 \u22125 \xB0C day and night")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 9 a 15 h","From 9 to 15 h")},{etiqueta:e("Roca","Rock"),valor:a("4 %, piedra suelta","4 %, loose stones")},{etiqueta:e("Flora","Flora"),valor:a("0,8\xD7, corros redondos de radio 3,8","0.8\xD7, round patches of radius 3.8")},{etiqueta:e("De noche","At night"),valor:a("La ara\xF1a","The spider")}],["mundo/sitio","mundo/invierno","mundo/clima"]),o("monzon","idioma",{es:{titulo:"El Monz\xF3n",subtitulo:"El sudeste asi\xE1tico: h\xFAmedo, cerrado y sin helada",resumen:"La casa de la tejedora. El bajo Mekong, 12\xB0 norte y 50 metros sobre el mar: clima tropical, c\xE1lido todo el a\xF1o y sin una sola escarcha, con la vegetaci\xF3n m\xE1s espesa del cat\xE1logo despu\xE9s del Amazonas. Roca en l\xEDneas de tres \u2014troncos y ra\xEDces\u2014 y la comida en manchas grandes por todas partes.",bloques:[{titulo:"El a\xF1o",texto:"Primavera y verano en el tope del term\xF3metro, 35 grados de d\xEDa y 35 de madrugada; oto\xF1o a 29 y 24; invierno a 19 de d\xEDa y 14 de noche. Las cuatro estaciones se trabajan enteras: aqu\xED el invierno solo se nota en que brota menos y en que la noche es un poco m\xE1s larga."},{titulo:"El suelo",texto:"Roca al 14 por ciento en l\xEDneas de tres casillas, en cualquier direcci\xF3n: troncos ca\xEDdos que cortan el paso y obligan a rodear, con claros entre medias. La flora es densa (1,4 veces la de siempre) y en manchas anchas: hay comida a la vuelta de cualquier tronco, y por eso hay vecinos a la vuelta de cualquier tronco."},{titulo:"La luz y la noche",texto:"El d\xEDa apenas cambia: de 11,3 horas en invierno a 12,7 en verano. La noche es de calor y salen las dos ara\xF1as, la de siempre y la errante, que caza a la hormiga que se queda sola y lejos."}],consejo:"Sin invierno que temer, lo que manda es el sitio: cada claro entre troncos es una despensa y un pasillo. La tejedora est\xE1 en casa \u2014sus muros de fibra cierran los pasos entre l\xEDneas de roca\u2014 y las dem\xE1s tienen que aprender a rodear.",palabras:["monz\xF3n","monzon","tropical","mekong","tejedora","oecophylla","sitio","asia","sudeste asi\xE1tico"]},en:{titulo:"The Monsoon",subtitulo:"Southeast Asia: humid, closed in and frost-free",resumen:"Home of the weaver ant. The lower Mekong, 12\xB0 north and 50 metres above the sea: tropical climate, warm all year without a single frost, and the thickest vegetation in the catalogue after the Amazon. Rock in lines of three \u2014 trunks and roots \u2014 and food in big patches everywhere.",bloques:[{titulo:"The year",texto:"Spring and summer at the top of the thermometer, 35 degrees by day and 35 before dawn; autumn at 29 and 24; winter at 19 by day and 14 by night. All four seasons can be worked in full: here winter shows only as fewer sprouts and a slightly longer night."},{titulo:"The ground",texto:"Rock at 14 percent in lines of three cells, in any direction: fallen trunks that cut the way and force you round, with clearings in between. Flora is dense (1.4 times the usual) and in wide patches: there is food round every trunk, which is why there are neighbours round every trunk."},{titulo:"Light and night",texto:"The day barely changes: from 11.3 hours in winter to 12.7 in summer. Nights are warm and both spiders come out, the usual one and the wandering one that hunts the ant left far and alone."}],consejo:"With no winter to fear, the ground is what rules: every clearing between trunks is a larder and a corridor. The weaver is at home here \u2014 her fibre walls close the gaps between lines of rock \u2014 and everyone else has to learn to go round.",palabras:["monsoon","tropical","mekong","weaver","oecophylla","place","asia","southeast asia"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Asia \xB7 12\xB0 norte \xB7 50 m","Asia \xB7 12\xB0 north \xB7 50 m")},{etiqueta:e("Clima","Climate"),valor:a("Tropical","Tropical")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("35 \xB0C de d\xEDa \xB7 19 \xB0C de d\xEDa y 14 de noche","35 \xB0C by day \xB7 19 \xB0C by day and 14 by night")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 11,3 a 12,7 h","From 11.3 to 12.7 h")},{etiqueta:e("Roca","Rock"),valor:a("14 %, en l\xEDneas de tres","14 %, in lines of three")},{etiqueta:e("Flora","Flora"),valor:a("1,4\xD7, manchas de radio 4,5","1.4\xD7, patches of radius 4.5")},{etiqueta:e("De noche","At night"),valor:a("La ara\xF1a y la ara\xF1a errante","The spider and the wandering spider")},{etiqueta:e("Su especie","Its species"),valor:a("La tejedora (Oecophylla)","The weaver ant (Oecophylla)")}],["especies/tejedora","mundo/sitio","mundo/noche","fauna/arana-errante"]),o("outback","idioma",{es:{titulo:"El Outback",subtitulo:"El centro de Australia: el d\xEDa quema y la noche se lo lleva",resumen:"La casa de la bulldog. El interior australiano, 25\xB0 sur y 400 metros de altura: clima des\xE9rtico, con el salto de temperatura m\xE1s grande del cat\xE1logo entre el mediod\xEDa y el amanecer. Roca escasa en domin\xF3s y una flora rala en manchas medianas: lejos de casa hay poco que comer.",bloques:[{titulo:"El a\xF1o",texto:"Primavera y oto\xF1o a 24 grados de d\xEDa y 4 de madrugada; verano a 35 con noches de 18; invierno a 12 al mediod\xEDa y cinco bajo cero antes del alba. Solo el verano est\xE1 libre de escarcha: el resto del a\xF1o la madrugada muerde aunque el d\xEDa haya sido templado, y ese es el rasgo del desierto. Est\xE1 en el hemisferio sur, pero el verano del juego es la estaci\xF3n c\xE1lida del sitio, as\xED que el a\xF1o se cuenta igual."},{titulo:"El suelo",texto:"Roca al 8 por ciento en domin\xF3s: campo abierto con piedras de dos que apenas cortan el paso. La flora es rala \u2014menos de la mitad de plantas que en la costa\u2014 en manchas medianas y separadas: cada una vale mucho y todo el mundo la ve desde lejos."},{titulo:"La luz y la noche",texto:"El d\xEDa va de 10,4 horas en pleno invierno a 13,6 en pleno verano. La noche es de calor y salen las dos ara\xF1as; en un campo tan abierto la errante encuentra pronto a la que se rezaga."}],consejo:"La bulldog est\xE1 en casa: ve lejos, corre y pega, que es lo que pide un campo abierto con la comida a trechos. Con cualquier otra especie, guarece a la colonia antes del amanecer fuera del verano, porque la helada de madrugada llega despu\xE9s de un d\xEDa de 24 grados y no se ve venir.",palabras:["outback","australia","desierto","des\xE9rtico","bulldog","myrmecia","sitio","ocean\xEDa","sur"]},en:{titulo:"The Outback",subtitulo:"Central Australia: the day burns and the night takes it all back",resumen:"Home of the bulldog ant. The Australian interior, 25\xB0 south and 400 metres up: desert climate, with the biggest swing in the catalogue between noon and dawn. Sparse rock in dominoes and thin flora in medium patches: far from home there is little to eat.",bloques:[{titulo:"The year",texto:"Spring and autumn at 24 degrees by day and 4 before dawn; summer at 35 with nights of 18; winter at 12 at noon and five below before daybreak. Only summer is free of frost: the rest of the year the dawn bites even after a mild day, and that is what makes a desert. It sits in the southern hemisphere, but the game\u2019s summer is the warm season of the place, so the year is counted the same way."},{titulo:"The ground",texto:"Rock at 8 percent in dominoes: open country with pairs of stones that hardly block the way. Flora is thin \u2014 under half the plants of the coast \u2014 in medium, scattered patches: each one is worth a lot and everyone can see it from afar."},{titulo:"Light and night",texto:"The day runs from 10.4 hours at midwinter to 13.6 at midsummer. Nights are warm and both spiders come out; in country this open the wandering one soon finds whoever lags behind."}],consejo:"The bulldog is at home: she sees far, runs and hits, which is what open country with food in stretches asks for. With any other species, shelter the colony before dawn outside summer, because the pre-dawn frost comes after a 24-degree day and cannot be seen coming.",palabras:["outback","australia","desert","bulldog","myrmecia","place","oceania","south"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Ocean\xEDa \xB7 25\xB0 sur \xB7 400 m","Oceania \xB7 25\xB0 south \xB7 400 m")},{etiqueta:e("Clima","Climate"),valor:a("Des\xE9rtico","Desert")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("35 \xB0C de d\xEDa \xB7 12 \xB0C de d\xEDa y \u22125 de madrugada","35 \xB0C by day \xB7 12 \xB0C by day and \u22125 before dawn")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 10,4 a 13,6 h","From 10.4 to 13.6 h")},{etiqueta:e("Roca","Rock"),valor:a("8 %, en domin\xF3s","8 %, in dominoes")},{etiqueta:e("Flora","Flora"),valor:a("0,45\xD7, manchas de radio 3,2","0.45\xD7, patches of radius 3.2")},{etiqueta:e("De noche","At night"),valor:a("La ara\xF1a errante y la ara\xF1a","The wandering spider and the spider")},{etiqueta:e("Su especie","Its species"),valor:a("La bulldog (Myrmecia)","The bulldog ant (Myrmecia)")}],["especies/bulldog","mundo/sitio","mundo/noche","fauna/arana-errante"]),o("caribe","idioma",{es:{titulo:"El Caribe",subtitulo:"Medio mapa es mar: una isla madre y cinco islas vac\xEDas",resumen:"Am\xE9rica, 18\xB0 norte, a veinte metros del mar. Es el \xFAnico sitio del cat\xE1logo donde el suelo NO es de una pieza: casi la mitad del mapa es agua, y la tierra son seis islas. Todas las colonias nacen en la isla madre, la del centro; las otras cinco est\xE1n vac\xEDas, tienen comida y solo se llega a ellas volando\u2026 o subi\xE9ndose a un tronco a la deriva.",bloques:[{titulo:"La isla madre",texto:"La grande, en el centro del mapa, y ah\xED nacen TODAS las colonias, sin excepci\xF3n. Las puertas est\xE1n m\xE1s juntas que en cualquier otro sitio \u2014el c\xEDrculo se encoge para que quepan en la isla\u2014 y ninguna nace a menos de siete casillas del agua, que es lo que mide el cono de un hormiguero de mil hormigas: por muy grande que se haga, un hormiguero nunca toca el mar. La guerra del Caribe se pelea aqu\xED."},{titulo:"Las otras islas",texto:"Cinco, de nueve a trece casillas de radio, separadas de la madre y entre s\xED por brazos de mar de tres a ocho casillas. Nacen vac\xEDas, pero NUNCA sin comida: cada una lleva su planta. Son la retaguardia \u2014 se llega volando (la reina en vuelo nupcial funda all\xED) o en un tronco a la deriva cuando toca tu orilla."},{titulo:"El clima",texto:"Tropical de verdad: no hiela jam\xE1s. Treinta y cinco grados al mediod\xEDa en primavera y verano, veintinueve en oto\xF1o y diecinueve en invierno, con madrugadas que no bajan de catorce. El d\xEDa casi no se mueve en todo el a\xF1o: de once a trece horas de luz. Aqu\xED no manda el reloj, manda el mar."}],consejo:"Piensa d\xF3nde est\xE1 tu orilla antes de expandirte. Una reina que vuela a una isla vac\xEDa tiene comida y nadie que la ataque a pie, pero tambi\xE9n se queda sin refuerzos: mira por d\xF3nde pasa la corriente de los troncos antes de dejarla sola.",palabras:["caribe","archipi\xE9lago","isla","islas","mar","agua","tropical","am\xE9rica","tronco","cortadora"]},en:{titulo:"The Caribbean",subtitulo:"Half the map is sea: one mother island and five empty ones",resumen:"America, 18\xB0 north, twenty metres above the sea. It is the only place in the catalogue where the ground is NOT in one piece: almost half the map is water, and the land is six islands. Every colony is born on the mother island, the one in the middle; the other five are empty, they have food, and you only reach them by flying\u2026 or by climbing onto a drifting log.",bloques:[{titulo:"The mother island",texto:"The big one, in the middle of the map, and EVERY colony is born there, without exception. The doors sit closer together than anywhere else \u2014 the circle shrinks so they all fit on the island \u2014 and none is born within seven cells of the water, which is the reach of the mound of a thousand-ant nest: however big it grows, a nest never touches the sea. The Caribbean war is fought here."},{titulo:"The other islands",texto:"Five of them, nine to thirteen cells in radius, kept apart from the mother and from each other by arms of sea three to eight cells wide. They are born empty, but NEVER without food: each one carries its own plant. They are the rear \u2014 reached by flying (a queen on her nuptial flight founds there) or on a drifting log when it touches your shore."},{titulo:"The climate",texto:"Properly tropical: it never freezes. Thirty-five degrees at noon in spring and summer, twenty-nine in autumn and nineteen in winter, with dawns that never drop below fourteen. The day hardly moves all year: eleven to thirteen hours of light. Here the clock does not rule, the sea does."}],consejo:"Think about where your shore is before you expand. A queen who flies to an empty island has food and nobody who can reach her on foot, but she also has no reinforcements: look at where the log current runs before you leave her alone.",palabras:["caribbean","archipelago","island","islands","sea","water","tropical","america","log","leafcutter"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Am\xE9rica \xB7 18\xB0 norte \xB7 20 m","America \xB7 18\xB0 north \xB7 20 m")},{etiqueta:e("Clima","Climate"),valor:a("Tropical: no hiela nunca","Tropical: it never freezes")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("35 \xB0C de d\xEDa \xB7 19 \xB0C de d\xEDa y 14 de madrugada","35 \xB0C by day \xB7 19 \xB0C by day and 14 before dawn")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 10,9 a 13,1 h","From 10.9 to 13.1 h")},{etiqueta:e("El mar","The sea"),valor:a("Casi la mitad del mapa","Almost half the map")},{etiqueta:e("Islas","Islands"),valor:a("6: la madre y cinco vac\xEDas","6: the mother and five empty")},{etiqueta:e("Roca","Rock"),valor:a("10 %, en domin\xF3s","10 %, in dominoes")},{etiqueta:e("Flora","Flora"),valor:a("1,3\xD7, manchas de radio 4,2","1.3\xD7, patches of radius 4.2")},{etiqueta:e("De noche","At night"),valor:a("La ara\xF1a errante y la ara\xF1a","The wandering spider and the spider")},{etiqueta:e("Su especie","Its species"),valor:a("La cortadora (Atta)","The leafcutter ant (Atta)")}],["especies/cortadora","mundo/sitio","mundo/agua","mundo/tronco"]),o("fiordo","idioma",{es:{titulo:"El Fiordo",subtitulo:"La costa noruega: el a\xF1o m\xE1s suave y los d\xEDas m\xE1s extremos",resumen:"Europa, 60\xB0 norte, a diez metros del agua. Clima oce\xE1nico: el mar amortigua el a\xF1o entero, as\xED que ni el verano quema ni el invierno baja de cero. Lo que manda aqu\xED es la luz, con el d\xEDa m\xE1s largo del cat\xE1logo en verano y el m\xE1s corto en invierno. No hay agua en el mapa: el fiordo es la costa que se pisa, un pedregal en domin\xF3s con la flora de siempre.",bloques:[{titulo:"El a\xF1o",texto:"Primavera a 17 grados de d\xEDa y 11 de madrugada; verano a 25 con noches de 19; oto\xF1o a 15 y 9; invierno a 7 al mediod\xEDa y 1 grado antes del alba. Es el a\xF1o m\xE1s suave del cat\xE1logo: la \xFAnica escarcha es la de las madrugadas de invierno, lenta y sin bajar de cero, y ninguna estaci\xF3n se pierde entera."},{titulo:"El suelo",texto:"Roca al 12 por ciento en domin\xF3s \u2014medido a 96 por lado, entre el 11,6 y el 13,6\u2014, un pedregal que entorpece el paso sin cerrar nada. La flora es la de siempre, ni densa ni rala, en manchas medianas. El sitio no destaca por el suelo: destaca por el cielo."},{titulo:"La luz y la noche",texto:"El d\xEDa va de 5,5 horas en pleno invierno a 18,5 en pleno verano, los dos extremos del cat\xE1logo. En verano casi no hay noche que aguantar; en invierno la ara\xF1a de siempre caza dieciocho horas seguidas y el poco sol que hay apenas caldea."}],consejo:"Aqu\xED el reloj es el sitio. Forrajea a destajo en el verano de dieciocho horas y ten la despensa a tope al entrar el oto\xF1o: el invierno no mata de fr\xEDo, mata de noche, con seis horas de luz y la ara\xF1a el resto.",palabras:["fiordo","oce\xE1nico","costero","noruega","luz","sitio","europa","norte"]},en:{titulo:"The Fjord",subtitulo:"The Norwegian coast: the mildest year and the most extreme days",resumen:"Europe, 60\xB0 north, ten metres from the water. Oceanic climate: the sea cushions the whole year, so summer never burns and winter never drops below zero. What rules here is the light, with the longest day in the catalogue in summer and the shortest in winter. There is no water on the map: the fjord is the shore you walk on, a scree in dominoes with the usual flora.",bloques:[{titulo:"The year",texto:"Spring at 17 degrees by day and 11 before dawn; summer at 25 with nights of 19; autumn at 15 and 9; winter at 7 at noon and 1 degree before daybreak. It is the mildest year in the catalogue: the only frost is that of winter dawns, slow and never below zero, and no season is lost entirely."},{titulo:"The ground",texto:"Rock at 12 percent in dominoes \u2014 measured at 96 a side, between 11.6 and 13.6 \u2014 a scree that hinders the way without closing anything. The flora is the usual one, neither dense nor thin, in medium patches. The place does not stand out for its ground: it stands out for its sky."},{titulo:"Light and night",texto:"The day runs from 5.5 hours at midwinter to 18.5 at midsummer, the two extremes of the catalogue. In summer there is hardly any night to sit through; in winter the usual spider hunts for eighteen hours straight and what little sun there is barely warms."}],consejo:"Here the clock is the place. Forage flat out through the eighteen-hour summer and have the larder full as autumn comes in: winter does not kill with cold, it kills with night, six hours of light and the spider for the rest.",palabras:["fjord","oceanic","coastal","norway","light","place","europe","north"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Europa \xB7 60\xB0 norte \xB7 10 m","Europe \xB7 60\xB0 north \xB7 10 m")},{etiqueta:e("Clima","Climate"),valor:a("Oce\xE1nico","Oceanic")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("25 \xB0C de d\xEDa \xB7 7 \xB0C de d\xEDa y 1 de madrugada","25 \xB0C by day \xB7 7 \xB0C by day and 1 before dawn")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 5,5 a 18,5 h","From 5.5 to 18.5 h")},{etiqueta:e("Roca","Rock"),valor:a("12 %, en domin\xF3s","12 %, in dominoes")},{etiqueta:e("Flora","Flora"),valor:a("1\xD7, manchas de radio 3,6","1\xD7, patches of radius 3.6")},{etiqueta:e("De noche","At night"),valor:a("La ara\xF1a","The spider")}],["mundo/sitio","mundo/clima","mundo/noche"]),o("cumbre","idioma",{es:{titulo:"La Cumbre",subtitulo:"Los Alpes: el invierno m\xE1s duro y un verano corto de verdad",resumen:"Europa, 46\xB0 norte, alta monta\xF1a. El fr\xEDo de la altura viene en el propio clima, y los 400 metros del sitio son el matiz. Hiela todas las noches del a\xF1o menos las de verano, y en invierno tambi\xE9n al mediod\xEDa. Es el sitio con m\xE1s roca del cat\xE1logo y con menos comida: se juega por los huecos.",bloques:[{titulo:"El a\xF1o",texto:"Primavera a 9 grados de d\xEDa y dos bajo cero de madrugada; verano a 24 con noches de 12; oto\xF1o a 10 y uno bajo cero; invierno a cinco bajo cero de d\xEDa y de noche. Solo el verano est\xE1 libre de escarcha, y en invierno la helada no levanta a ninguna hora: el a\xF1o entero se juega a llegar al buen tiempo con la colonia en pie y a aprovecharlo."},{titulo:"El suelo",texto:"Roca al 22 por ciento, el tope del cat\xE1logo, en pedregal fragmentado: bloques de dos por dos y l\xEDneas de cuatro. Medido a 96 por lado sale entre el 22 y el 25. La flora es la m\xE1s escasa de todos los sitios \u2014un tercio de las plantas de siempre\u2014 en manchas peque\xF1as: cada corro vale una estaci\xF3n."},{titulo:"La luz y la noche",texto:"El d\xEDa va de 8,4 horas en pleno invierno a 15,6 en pleno verano. De noche caza la ara\xF1a de siempre, y con tanta roca los pasos entre bloques son donde encuentra a la que vuelve tarde."}],consejo:"Cava hondo y pronto: el verano es la \xFAnica estaci\xF3n para salir lejos, y lo que no est\xE9 en la despensa al caer el oto\xF1o ya no llega. Los pasos entre pedregales se cierran con pocas hormigas; \xFAsalos a tu favor.",palabras:["cumbre","monta\xF1a","alta monta\xF1a","alpes","pedregal","sitio","europa","fr\xEDo"]},en:{titulo:"The Summit",subtitulo:"The Alps: the harshest winter and a short but real summer",resumen:"Europe, 46\xB0 north, high mountain. The cold of altitude comes built into the climate itself, and the 400 metres of the place are the nuance. It frosts every night of the year except the summer ones, and in winter at noon as well. It is the place with the most rock in the catalogue and the least food: you play through the gaps.",bloques:[{titulo:"The year",texto:"Spring at 9 degrees by day and two below zero before dawn; summer at 24 with nights of 12; autumn at 10 and one below; winter at five below by day and by night. Only summer is free of frost, and in winter the freeze never lifts at any hour: the whole year is a race to reach the good weather with the colony standing, and to make the most of it."},{titulo:"The ground",texto:"Rock at 22 percent, the top of the catalogue, in broken scree: two-by-two blocks and lines of four. Measured at 96 a side it comes out between 22 and 25. The flora is the scarcest of any place \u2014 a third of the usual plants \u2014 in small patches: each one is worth a season."},{titulo:"Light and night",texto:"The day runs from 8.4 hours at midwinter to 15.6 at midsummer. At night the usual spider hunts, and with this much rock the gaps between blocks are where it finds whoever comes home late."}],consejo:"Dig deep and early: summer is the only season for ranging far, and whatever is not in the larder when autumn falls will never arrive. The gaps between scree fields are closed with a handful of ants; use them to your advantage.",palabras:["summit","mountain","high mountain","alps","scree","place","europe","cold"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Europa \xB7 46\xB0 norte \xB7 400 m","Europe \xB7 46\xB0 north \xB7 400 m")},{etiqueta:e("Clima","Climate"),valor:a("Alta monta\xF1a","High mountain")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("24 \xB0C de d\xEDa \xB7 \u22125 \xB0C de d\xEDa y de noche","24 \xB0C by day \xB7 \u22125 \xB0C day and night")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 8,4 a 15,6 h","From 8.4 to 15.6 h")},{etiqueta:e("Roca","Rock"),valor:a("22 %, pedregal de bloques y l\xEDneas de cuatro","22 %, scree of blocks and lines of four")},{etiqueta:e("Flora","Flora"),valor:a("0,35\xD7, manchas de radio 2,6","0.35\xD7, patches of radius 2.6")},{etiqueta:e("De noche","At night"),valor:a("La ara\xF1a","The spider")}],["mundo/sitio","mundo/invierno","hormiguero/despensa"]),o("taiga","idioma",{es:{titulo:"La Taiga",subtitulo:"El bosque boreal: la casa de la roja, y el a\xF1o m\xE1s duro",resumen:"La casa de la roja. El bosque boreal a 58\xB0 norte y 250 metros: clima continental en el norte de verdad, con el verano en el tope del term\xF3metro y un invierno que hiela de d\xEDa y de noche con seis horas de luz. Troncos ca\xEDdos en l\xEDneas de tres y la comida en claros peque\xF1os y escasos.",bloques:[{titulo:"El a\xF1o",texto:"Primavera a 16 grados de d\xEDa y dos bajo cero de madrugada; verano a 35 con noches de 17; oto\xF1o a 13 y cinco bajo cero; invierno a cinco bajo cero a cualquier hora. Un a\xF1o de dos caras: el verano da calor y luz de sobra, y las otras tres estaciones escarchan de madrugada. Junta el invierno continental con la noche larga del norte, y por eso es el sitio m\xE1s duro del cat\xE1logo."},{titulo:"El suelo",texto:"Roca al 16 por ciento en l\xEDneas de tres \u2014troncos ca\xEDdos en cualquier direcci\xF3n\u2014, medido a 96 por lado entre el 15,6 y el 19. La flora es escasa, seis de cada diez plantas de las de siempre, en manchas cortas: los claros donde brota son pocos y todo el mundo los conoce."},{titulo:"La luz y la noche",texto:"El d\xEDa va de 6,1 horas en pleno invierno a 17,9 en pleno verano. De noche caza la ara\xF1a de siempre, y en invierno tiene dieciocho horas para hacerlo."}],consejo:"La roja est\xE1 en casa: levanta una colonia grande y dif\xEDcil de desalojar, que es lo que pide un sitio donde se pasa medio a\xF1o bajo techo. Con cualquier especie, el verano es la partida entera: expande, llena la despensa y vuelve dentro antes de que el oto\xF1o escarche.",palabras:["taiga","bosque","boreal","continental","roja","formica","sitio","europa","norte"]},en:{titulo:"The Taiga",subtitulo:"The boreal forest: home of the red wood ant, and the harshest year",resumen:"Home of the red wood ant. The boreal forest at 58\xB0 north and 250 metres: a continental climate in the true north, with summer at the top of the thermometer and a winter that freezes day and night on six hours of light. Fallen trunks in lines of three and food in small, scarce clearings.",bloques:[{titulo:"The year",texto:"Spring at 16 degrees by day and two below zero before dawn; summer at 35 with nights of 17; autumn at 13 and five below; winter at five below at any hour. A two-faced year: summer gives heat and light to spare, and the other three seasons frost before dawn. Put the continental winter together with the long northern night, and that is why it is the harshest place in the catalogue."},{titulo:"The ground",texto:"Rock at 16 percent in lines of three \u2014 fallen trunks in any direction \u2014 measured at 96 a side between 15.6 and 19. The flora is scarce, six in ten of the usual plants, in short patches: the clearings where food sprouts are few and everyone knows them."},{titulo:"Light and night",texto:"The day runs from 6.1 hours at midwinter to 17.9 at midsummer. At night the usual spider hunts, and in winter it has eighteen hours to do so."}],consejo:"The red wood ant is at home: she raises a large colony that is hard to dislodge, which is what a place where half the year is spent indoors asks for. With any species, summer is the whole match: expand, fill the larder and get back inside before autumn frosts.",palabras:["taiga","forest","boreal","continental","red wood ant","formica","place","europe","north"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Europa \xB7 58\xB0 norte \xB7 250 m","Europe \xB7 58\xB0 north \xB7 250 m")},{etiqueta:e("Clima","Climate"),valor:a("Continental","Continental")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("35 \xB0C de d\xEDa \xB7 \u22125 \xB0C de d\xEDa y de noche","35 \xB0C by day \xB7 \u22125 \xB0C day and night")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 6,1 a 17,9 h","From 6.1 to 17.9 h")},{etiqueta:e("Roca","Rock"),valor:a("16 %, en l\xEDneas de tres","16 %, in lines of three")},{etiqueta:e("Flora","Flora"),valor:a("0,6\xD7, manchas de radio 3","0.6\xD7, patches of radius 3")},{etiqueta:e("De noche","At night"),valor:a("La ara\xF1a","The spider")},{etiqueta:e("Su especie","Its species"),valor:a("La roja (Formica rufa)","The red wood ant (Formica rufa)")}],["especies/roja","mundo/sitio","mundo/invierno","mundo/noche"]),o("sabana","idioma",{es:{titulo:"La Sabana",subtitulo:"El altiplano africano: campo abierto y sin helada",resumen:"\xC1frica, 10\xB0 norte y 900 metros de altura, en un altiplano tropical. La altura le quita seis grados al tr\xF3pico y aun as\xED no hiela nunca: el a\xF1o se nota en cu\xE1nto brota, no en el term\xF3metro. Es campo abierto de verdad \u2014apenas roca, hierba rala y lejos\u2014 y se camina mucho para todo. Ninguna especie del juego tiene aqu\xED su casa.",bloques:[{titulo:"El a\xF1o",texto:"Primavera a 29 grados de d\xEDa y 24 de madrugada; verano a 35 de d\xEDa y de noche, el tope del term\xF3metro; oto\xF1o a 23 y 18; invierno a 13 al mediod\xEDa y 8 antes del alba. Sin una sola escarcha: el invierno solo se nota en que brota un tercio y en que la noche es un poco m\xE1s larga."},{titulo:"El suelo",texto:"Roca al 6 por ciento en domin\xF3s \u2014medido a 96 por lado, entre el 5,5 y el 7,7\u2014, piedras de dos que no cortan nada. La flora es rala, la mitad de plantas de las de siempre, en manchas medianas y separadas: entre corro y corro hay mucho suelo raso, y quien lo cruza se ve desde lejos."},{titulo:"La luz y la noche",texto:"El d\xEDa casi no cambia: de 11,4 horas en invierno a 12,6 en verano. La noche es de calor y salen las dos ara\xF1as, la de siempre y la errante, que en un campo as\xED de abierto encuentra pronto a la que se rezaga."}],consejo:"Sin invierno que temer ni muros que aprovechar, la partida es de distancias: levanta el segundo hormiguero al lado de un corro, no a media marcha de tres, y no dejes columnas largas fuera de noche.",palabras:["sabana","tropical","altiplano","hierba","campo abierto","sitio","\xE1frica"]},en:{titulo:"The Savannah",subtitulo:"The African plateau: open country with no frost",resumen:"Africa, 10\xB0 north and 900 metres up, on a tropical plateau. The altitude takes six degrees off the tropics and it still never freezes: the year shows in how much sprouts, not on the thermometer. It is truly open country \u2014 hardly any rock, thin grass and far apart \u2014 and you walk a long way for everything. No species in the game has its home here.",bloques:[{titulo:"The year",texto:"Spring at 29 degrees by day and 24 before dawn; summer at 35 by day and by night, the top of the thermometer; autumn at 23 and 18; winter at 13 at noon and 8 before daybreak. Not a single frost: winter shows only in a third of the sprouts and a slightly longer night."},{titulo:"The ground",texto:"Rock at 6 percent in dominoes \u2014 measured at 96 a side, between 5.5 and 7.7 \u2014 pairs of stones that cut nothing. The flora is thin, half the usual plants, in medium, scattered patches: between one patch and the next there is a lot of bare ground, and whoever crosses it can be seen from afar."},{titulo:"Light and night",texto:"The day barely changes: from 11.4 hours in winter to 12.6 in summer. Nights are warm and both spiders come out, the usual one and the wandering one, which in country this open soon finds whoever lags behind."}],consejo:"With no winter to fear and no walls to lean on, the match is about distances: raise the second anthill next to a patch, not halfway between three, and leave no long columns outside at night.",palabras:["savannah","savanna","tropical","plateau","grass","open country","place","africa"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("\xC1frica \xB7 10\xB0 norte \xB7 900 m","Africa \xB7 10\xB0 north \xB7 900 m")},{etiqueta:e("Clima","Climate"),valor:a("Tropical","Tropical")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("35 \xB0C de d\xEDa y de noche \xB7 13 \xB0C de d\xEDa y 8 de madrugada","35 \xB0C day and night \xB7 13 \xB0C by day and 8 before dawn")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 11,4 a 12,6 h","From 11.4 to 12.6 h")},{etiqueta:e("Roca","Rock"),valor:a("6 %, en domin\xF3s","6 %, in dominoes")},{etiqueta:e("Flora","Flora"),valor:a("0,5\xD7, manchas de radio 3","0.5\xD7, patches of radius 3")},{etiqueta:e("De noche","At night"),valor:a("La ara\xF1a y la ara\xF1a errante","The spider and the wandering spider")}],["mundo/sitio","mundo/noche","fauna/arana-errante"]),o("oasis","idioma",{es:{titulo:"El Oasis",subtitulo:"El S\xE1hara: cuatro fuentes y nada alrededor",resumen:"\xC1frica, 27\xB0 norte y 300 metros, en pleno desierto. Clima des\xE9rtico: no lo define el calor sino el salto de veinte grados entre el mediod\xEDa y el amanecer, y por eso hiela de madrugada en invierno tras un d\xEDa de 13. Es el \xFAnico sitio donde la comida no brota a manchas por todo el mapa: casi toda cae junto a cuatro fuentes sim\xE9tricas. Ninguna especie del juego tiene aqu\xED su casa.",bloques:[{titulo:"El a\xF1o",texto:"Primavera y oto\xF1o a 25 grados de d\xEDa y 5 de madrugada; verano a 35 con noches de 19; invierno a 13 al mediod\xEDa y cinco bajo cero antes del alba. Solo el verano libra de la escarcha; el resto del a\xF1o la madrugada baja de los cinco grados aunque el d\xEDa haya sido templado, y eso es lo que hace desierto al desierto."},{titulo:"El suelo",texto:"Roca con el sorteo de siempre, en piedra suelta: medido a 96 por lado, entre el 16,6 y el 19,8 por ciento. Lo que cambia es la comida: el 85 por ciento de los brotes cae alrededor de cuatro fuentes sim\xE9tricas, lejos de todos los nidos y separadas entre s\xED, y el resto disperso por el mapa. No hay plantas escondidas que descubrir: se sabe d\xF3nde est\xE1 la comida, y todos van all\xED."},{titulo:"La luz y la noche",texto:"El d\xEDa va de 10,3 horas en pleno invierno a 13,7 en pleno verano. La noche es de calor y salen las dos ara\xF1as; la errante ronda los caminos de las fuentes, que es por donde va todo el mundo."}],consejo:"La partida es por las fuentes: quien se queda con dos come, y quien se queda sin ninguna se apaga. Levanta el segundo hormiguero pegado a una y defiende el camino, no el nido. Fuera del verano, todas dentro antes del alba.",palabras:["oasis","desierto","des\xE9rtico","s\xE1hara","fuentes","sitio","\xE1frica"]},en:{titulo:"The Oasis",subtitulo:"The Sahara: four springs and nothing around them",resumen:"Africa, 27\xB0 north and 300 metres, deep in the desert. Desert climate: it is defined not by heat but by the twenty-degree drop between noon and dawn, which is why it frosts before dawn in winter after a 13-degree day. It is the only place where food does not sprout in patches all over the map: almost all of it falls beside four symmetric springs. No species in the game has its home here.",bloques:[{titulo:"The year",texto:"Spring and autumn at 25 degrees by day and 5 before dawn; summer at 35 with nights of 19; winter at 13 at noon and five below before daybreak. Only summer is spared the frost; the rest of the year the dawn drops below five degrees even after a mild day, and that is what makes a desert a desert."},{titulo:"The ground",texto:"Rock from the usual draw, as loose stones: measured at 96 a side, between 16.6 and 19.8 percent. What changes is the food: 85 percent of the sprouts fall around four symmetric springs, far from every nest and apart from each other, and the rest is scattered across the map. There are no hidden plants to discover: everyone knows where the food is, and everyone goes there."},{titulo:"Light and night",texto:"The day runs from 10.3 hours at midwinter to 13.7 at midsummer. Nights are warm and both spiders come out; the wandering one prowls the paths to the springs, which is where everyone walks."}],consejo:"The match is for the springs: whoever holds two eats, and whoever holds none fades. Raise the second anthill right beside one and defend the path, not the nest. Outside summer, everyone inside before dawn.",palabras:["oasis","desert","sahara","springs","place","africa"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("\xC1frica \xB7 27\xB0 norte \xB7 300 m","Africa \xB7 27\xB0 north \xB7 300 m")},{etiqueta:e("Clima","Climate"),valor:a("Des\xE9rtico","Desert")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("35 \xB0C de d\xEDa \xB7 13 \xB0C de d\xEDa y \u22125 de madrugada","35 \xB0C by day \xB7 13 \xB0C by day and \u22125 before dawn")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 10,3 a 13,7 h","From 10.3 to 13.7 h")},{etiqueta:e("Roca","Rock"),valor:a("Del 17 al 20 %, piedra suelta","17 to 20 %, loose stones")},{etiqueta:e("Comida","Food"),valor:a("El 85 % junto a cuatro fuentes","85 % beside four springs")},{etiqueta:e("De noche","At night"),valor:a("La ara\xF1a y la ara\xF1a errante","The spider and the wandering spider")}],["mundo/sitio","mundo/noche","fauna/arana-errante","hormiguero/despensa"]),o("amazonas","idioma",{es:{titulo:"El Amazonas",subtitulo:"La selva ecuatorial: sin a\xF1o, y espesa",resumen:"La casa de la cortadora. La cuenca del Amazonas, 3\xB0 sur y 100 metros sobre el mar: clima ecuatorial, el \xFAnico que no tiene a\xF1o \u2014las cuatro estaciones caben en dos grados\u2014 y doce horas de luz los trescientos sesenta y cinco d\xEDas. El suelo m\xE1s espeso del cat\xE1logo: troncos en l\xEDneas de tres, la flora m\xE1s densa y comida por todas partes.",bloques:[{titulo:"El a\xF1o",texto:"Primavera y oto\xF1o a 27 grados de d\xEDa y 23 de madrugada; verano a 28 y 24; invierno a 26 y 22. La estaci\xF3n no es informaci\xF3n: no hiela nunca, la noche apenas refresca cuatro grados y lo \xFAnico que cambia con el a\xF1o es cu\xE1nto brota."},{titulo:"El suelo",texto:"Roca al 20 por ciento en l\xEDneas de tres \u2014troncos ca\xEDdos en cualquier direcci\xF3n\u2014, medido a 96 por lado entre el 19 y el 24. La flora es la m\xE1s densa del cat\xE1logo, una vez y media la de siempre en manchas grandes: hay comida a la vuelta de cada tronco y, por lo mismo, vecinos a la vuelta de cada tronco."},{titulo:"La luz y la noche",texto:"El d\xEDa es siempre el mismo: de 11,8 a 12,2 horas. La noche es de calor y salen las dos ara\xF1as, la de siempre y la errante; entre tanto tronco, la que se queda sola tarda en ver venir a nadie."}],consejo:"La cortadora est\xE1 en casa: hormigueros enormes y obreras baratas para un sitio donde sobra comida y falta sitio. Sin invierno ni noche larga, aqu\xED no se sobrevive, se compite: cada claro es una despensa y todos los caminos rodean troncos, as\xED que quien controla los pasos controla la comida.",palabras:["amazonas","selva","ecuatorial","cortadora","atta","sitio","am\xE9rica","sudam\xE9rica","sin estaciones"]},en:{titulo:"The Amazon",subtitulo:"The equatorial rainforest: no year, and thick",resumen:"Home of the leafcutter ant. The Amazon basin, 3\xB0 south and 100 metres above the sea: equatorial climate, the only one with no year at all \u2014 the four seasons fit within two degrees \u2014 and twelve hours of light all three hundred and sixty-five days. The thickest ground in the catalogue: trunks in lines of three, the densest flora and food everywhere.",bloques:[{titulo:"The year",texto:"Spring and autumn at 27 degrees by day and 23 before dawn; summer at 28 and 24; winter at 26 and 22. The season is not information: it never freezes, the night cools by barely four degrees and the only thing the year changes is how much sprouts."},{titulo:"The ground",texto:"Rock at 20 percent in lines of three \u2014 fallen trunks in any direction \u2014 measured at 96 a side between 19 and 24. The flora is the densest in the catalogue, one and a half times the usual in big patches: there is food round every trunk and, for the same reason, neighbours round every trunk."},{titulo:"Light and night",texto:"The day is always the same: from 11.8 to 12.2 hours. Nights are warm and both spiders come out, the usual one and the wandering one; among so many trunks, the ant left alone is slow to see anything coming."}],consejo:"The leafcutter is at home: enormous anthills and cheap workers for a place with food to spare and no room. With no winter and no long night, here you do not survive, you compete: every clearing is a larder and every path goes round trunks, so whoever controls the gaps controls the food.",palabras:["amazon","rainforest","jungle","equatorial","leafcutter","atta","place","america","south america","no seasons"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Am\xE9rica \xB7 3\xB0 sur \xB7 100 m","America \xB7 3\xB0 south \xB7 100 m")},{etiqueta:e("Clima","Climate"),valor:a("Ecuatorial","Equatorial")},{etiqueta:e("Verano / invierno","Summer / winter"),valor:a("28 \xB0C de d\xEDa \xB7 26 \xB0C de d\xEDa y 22 de madrugada","28 \xB0C by day \xB7 26 \xB0C by day and 22 before dawn")},{etiqueta:e("El d\xEDa","The day"),valor:a("De 11,8 a 12,2 h","From 11.8 to 12.2 h")},{etiqueta:e("Roca","Rock"),valor:a("20 %, en l\xEDneas de tres","20 %, in lines of three")},{etiqueta:e("Flora","Flora"),valor:a("1,6\xD7, manchas de radio 5","1.6\xD7, patches of radius 5")},{etiqueta:e("De noche","At night"),valor:a("La ara\xF1a y la ara\xF1a errante","The spider and the wandering spider")},{etiqueta:e("Su especie","Its species"),valor:a("La cortadora (Atta)","The leafcutter ant (Atta)")}],["especies/cortadora","mundo/sitio","mundo/noche","fauna/arana-errante"]),o("noche","ojo",{es:{titulo:"La noche",subtitulo:"Menos vista, otras amenazas",resumen:"Al caer la luz el mapa se cierra: se explora menos lejos, los insectos del d\xEDa desaparecen y sale a cazar la ara\xF1a. A la que anda se la ve venir; a la que vuela se la lleva la noche sin que se vea qu\xE9 fue.",bloques:[{titulo:"La vista",texto:"El radio con el que una hormiga destapa niebla, localiza comida Y DETECTA al enemigo va CON LA LUZ: a pleno d\xEDa ve algo m\xE1s lejos que su rasgo y en noche cerrada se queda en la d\xE9cima parte \u2014pr\xE1cticamente ciega\u2014. De noche no solo ve menos: descubre y engancha al enemigo dentro de ese mismo radio menguado, as\xED que reacciona tarde y pelea peor."},{titulo:"La ara\xF1a errante",texto:"De noche sale a cazar una ara\xF1a, y caza como cazan de verdad: se acerca a la hormiga que pilla lejos y sola, la mata y SE RETIRA A DIGERIRLA \u2014 una pieza por salida. Sale una por colonia, y a la que anda no se la lleva nadie sin aviso: la ara\xF1a se ve venir, y cualquier hormiga con orden de CAZAR la para antes de que cobre. Lo que la alimenta es la hormiga rezagada. A la que va POR EL AIRE no la caza ella: a esa se la lleva la noche en el acto, reina incluida \u2014 el vuelo nupcial se hace de d\xEDa o se paga."},{titulo:"El relevo de la fauna",texto:"Los insectos diurnos se retiran al anochecer y no brota ninguno hasta el alba. Las carcasas del d\xEDa siguen en el suelo y se pueden despiezar."}],consejo:"Guarece a la colonia antes del anochecer, y usa la marcha \xABhasta el amanecer\xBB para no mirar la espera.",palabras:["noche","ara\xF1a","arana","vista","amanecer","cazar","vuelo"]},en:{titulo:"The night",subtitulo:"Less sight, other threats",resumen:"When the light falls the map closes in: you scout less far, daytime insects vanish and the spider comes out to hunt. What walks sees it coming; what flies is taken by the night without you ever seeing what did it.",bloques:[{titulo:"Sight",texto:"The radius an ant uses to lift fog, spot food AND pick out an enemy GOES WITH THE LIGHT: in broad daylight it reaches a little past her trait, and in full night it falls to a tenth \u2014 all but blind. At night she does not only see less: she spots and engages the enemy within that same shrunken radius, so she reacts late and fights worse."},{titulo:"The wandering spider",texto:"At night a spider goes hunting, and it hunts the way hunters do: it closes on the ant it catches far and alone, kills her and WITHDRAWS TO DIGEST \u2014 one kill per outing. One comes out per colony, and nothing takes a walking ant without warning: the spider can be seen coming, and any ant with the HUNT order stops it before it collects. What feeds it is the ant that lags behind. It does not hunt what is IN THE AIR: that one the night takes on the spot, queens included \u2014 the nuptial flight happens by day or it is paid for."},{titulo:"The wildlife shift",texto:"Daytime insects withdraw at dusk and none sprout until dawn. The day\u2019s carcasses stay on the ground and can still be butchered."}],consejo:"Shelter the colony before nightfall, and use the \u201Cuntil dawn\u201D gear so you don\u2019t watch the wait.",palabras:["night","spider","sight","dawn","hunt","flight"]}},null,["mundo/clima","mundo/fauna","mundo/invierno"]),o("invierno","candado",{es:{titulo:"El invierno",subtitulo:"La estaci\xF3n que se pasa bajo techo",resumen:"Brota un tercio de comida, los d\xEDas son cortos y bajo cinco grados el exterior congela. Se sobrevive con lo acumulado en las estaciones buenas.",bloques:[{titulo:"La helada",texto:"Por debajo de cinco grados cada turno fuera acumula escarcha, m\xE1s deprisa cuanto m\xE1s arrecia el fr\xEDo, y en plena helada unos ciento veinte turnos a la intemperie son la sentencia \u2014y no todas aguantan igual\u2014. Pasar una noche de invierno fuera ni se intenta. El deshielo o guarecerse la borran del todo. Cu\xE1nto muerde depende de D\xD3NDE juegues: el oce\xE1nico apenas hiela, el continental hiela tambi\xE9n de d\xEDa, y hay dos \u2014el tropical y el ecuatorial\u2014 donde la escarcha no existe y el invierno solo se nota en que brota menos."},{titulo:"El letargo",texto:"Con hielo las hormigas se arrastran: en helada cerrada andan a la d\xE9cima parte de su paso, y el fr\xEDo las va frenando desde los cinco grados. La que sale lejos no vuelve \u2014 no le da tiempo."},{titulo:"El acopio",texto:"La reserva de comida es local: cada hormiguero consume la suya. Ll\xE9nalas en primavera y verano, cava granero y pasa el invierno con la guarnici\xF3n dentro."}],consejo:"El invierno no es para ganar terreno: es para llegar vivo a la primavera con la comida almacenada a\xFAn a la mitad.",palabras:["invierno","helada","acopio","comida almacenada","despensa","escarcha"]},en:{titulo:"The winter",subtitulo:"The season you spend indoors",resumen:"A third of the food sprouts, days are short and below five degrees the outside freezes. You survive on what the good seasons stored.",bloques:[{titulo:"The freeze",texto:"Below five degrees every turn outside builds frost, faster the harder the cold bites, and in a full freeze about one hundred twenty turns in the open are a death sentence \u2014and not every ant lasts the same\u2014. Spending a winter night outside is not even worth trying. Thaw or shelter wipes it clean. How hard it bites depends on WHERE you play: the oceanic one barely freezes, the continental one freezes by day as well, and there are two \u2014 tropical and equatorial \u2014 where frost does not exist at all and winter shows up only as fewer sprouts."},{titulo:"Torpor",texto:"On ice ants crawl: in a hard freeze they walk at a tenth of their stride, and the cold slows them from five degrees down. The one that ranges far does not come back \u2014 there is no time."},{titulo:"Stockpiling",texto:"Food storage is local: each anthill consumes its own reserve. Fill it in spring and summer, dig granary space, and spend the winter with the garrison inside."}],consejo:"Winter is not for taking ground: it is for reaching spring alive with the stored food still half full.",palabras:["winter","freeze","stockpile","stored food","pantry","frost"]}},null,["mundo/clima","mundo/sitio","hormiguero/despensa"]),o("fauna","bicho",{es:{titulo:"Los bichos del campo",subtitulo:"Comida que anda, y algunos que te comen a ti",resumen:"El campo est\xE1 vivo: presas que huyen, herb\xEDvoras que se zampan tu comida y cazadoras que se llevan hormigas. Todo bicho abatido queda de carcasa, y la carcasa se despieza en el sitio: cada hormiga pegada arranca su trozo y lo apunta a la despensa de su hormiguero.",bloques:[{titulo:"Tres dietas",texto:"La PRESA solo huye \u2014pulg\xF3n, mariquita, escarabajo\u2014 y es comida con patas. La HERB\xCDVORA (oruga, saltamontes) busca tus migas, se las come y ENGORDA con ellas: cazarla recupera parte de lo que se llev\xF3. La INSECT\xCDVORA va a por tus hormigas: la avispa persigue, pica con el abdomen y, herida o rodeada, se escapa por el aire."},{titulo:"Morder es querer",texto:"Al bicho manso solo lo muerde quien va a por \xE9l, con la orden de CAZAR o de ATACAR: cruzarse con uno ya no lo mata. Al que muerde se le defiende todo el mundo, porque el que ataca es \xE9l. Y la presa acorralada cobra el despiece: un escarabajo cocea y una oruga se sacude, as\xED que la pieza grande cuesta cerca de una hormiga."},{titulo:"La estaci\xF3n decide qui\xE9n sale",texto:"Los brotes reponen el campo cada pocas decenas de turnos, en tandas y nunca junto a un hormiguero. Con estaciones, en primavera y verano brotan los pac\xEDficos y en oto\xF1o e invierno los que muerden. De noche el campo se vac\xEDa. Y si en el di\xE1logo de partida pones Amenazas: Ninguna, no hay fauna en absoluto: ni brotes, ni ara\xF1a, ni marabunta."}],consejo:"Una carcasa es una despensa que no se mueve: manda varias a despiezarla y entra a trozos. Y LO QUE PAGA SE VE A OJO \u2014 la carne de un bicho va con su tama\xF1o, as\xED que la lib\xE9lula llena la despensa y el pulg\xF3n es una propina\u2014; lo que cambia es lo que cuesta: la grande te pide manada y la peque\xF1a sale gratis.",palabras:["fauna","bichos","insectos","avispa","oruga","escarabajo","carcasa","despiece","cazar","amenazas"]},en:{titulo:"The creatures of the field",subtitulo:"Food that walks, and a few that eat you",resumen:"The field is alive: prey that flees, herbivores that devour your food and hunters that carry off ants. Every creature brought down is left as a carcass, and a carcass is butchered where it lies: each ant next to it tears off its share and books it to its own anthill pantry.",bloques:[{titulo:"Three diets",texto:"PREY only flees \u2014 aphid, ladybird, beetle \u2014 and is food on legs. The HERBIVORE (caterpillar, grasshopper) hunts for your crumbs, eats them and FATTENS on them: killing it recovers part of what it took. The INSECTIVORE comes for your ants: the wasp chases, stings with its abdomen and, wounded or surrounded, escapes through the air."},{titulo:"Biting means meaning it",texto:"A harmless creature is only bitten by ants that came for it, under the HUNT or ATTACK order: bumping into one no longer kills it. Whatever bites is fought by everyone, because it is the one attacking. And cornered prey charges for the butchering: a beetle kicks and a caterpillar thrashes, so a big carcass costs close to one ant."},{titulo:"The season picks who shows up",texto:"Spawns restock the field every few dozen turns, in batches and never beside an anthill. With seasons on, spring and summer bring out the harmless ones and autumn and winter the biting ones. At night the field empties. And if you set Threats: None in the match dialog there is no wildlife at all: no spawns, no spider, no army ants."}],consejo:"A carcass is a pantry that does not run: send several ants to butcher it and it comes home in pieces. AND WHAT IT PAYS IS VISIBLE \u2014 a creature\u2019s meat follows its size, so a dragonfly fills the pantry and an aphid is a tip; what changes is the price: a big one asks for a pack, a small one is free.",palabras:["wildlife","fauna","insects","wasp","caterpillar","beetle","carcass","butcher","hunt","threats"]}},[{etiqueta:e("Dietas","Diets"),valor:a("Presa \xB7 herb\xEDvora \xB7 insect\xEDvora","Prey \xB7 herbivore \xB7 insectivore")},{etiqueta:e("Bichos vivos a la vez","Creatures alive at once"),valor:a("De 2 a 40, seg\xFAn amenazas","From 2 to 40, by threat level")},{etiqueta:e("Sin fauna","No wildlife"),valor:a("Amenazas: Ninguna","Threats: None")}],["fauna/pulgon","fauna/avispa","fauna/arana","mundo/marabunta","mundo/noche","hormiguero/despensa"]),o("marabunta","hormiga",{es:{titulo:"La marabunta",subtitulo:"Un frente anunciado que cruza el mapa y se va",resumen:"Cada varios miles de turnos se pone en marcha un frente de legionarias. No es una emboscada: se anuncia con antelaci\xF3n, se dice por d\xF3nde entra y la barra cuenta lo que falta. Entra por un borde, cruza en l\xEDnea recta mordiendo lo que se le pone delante y se va por el otro lado.",bloques:[{titulo:"El aviso",texto:"Doscientos turnos antes salta el anuncio con el rumbo \u2014por el este, por el oeste, por el norte o por el sur\u2014 y un contador de lo que queda. Con estaciones solo llega en oto\xF1o e invierno, que es cuando el campo se pone bravo. Mientras el frente cruza, no brota ning\xFAn otro bicho."},{titulo:"El frente",texto:"Llega formado en l\xEDnea perpendicular a su rumbo y avanza SIEMPRE: no duerme de noche, no se para a esperar y no le hace falta que nadie la vea. No persigue a nadie \u2014muerde lo que le queda al paso\u2014 y cada una aguanta poqu\xEDsimo y deja poca carne. Lo que hace da\xF1o es que son muchas y no se desv\xEDan."},{titulo:"Contrajuego",texto:"Tres, y se eligen con el aviso en la mano: guarecer a la colonia, apartar del corredor lo que est\xE9 en su camino, o plantarle un muro de guerreras. A la marabunta se le defiende todo el mundo por estar pegada, pero la orden de CAZAR no la toma como objetivo: contra ella se ATACA o se aguanta."}],consejo:"Cuando salte el aviso, mira el rumbo antes que el reloj: apartar una columna cuesta unos turnos de marcha, y que la pille cargada cuesta la columna entera.",palabras:["marabunta","legionarias","frente","evento","aviso","amenazas"]},en:{titulo:"The army ants",subtitulo:"An announced front that crosses the map and leaves",resumen:"Every few thousand turns a front of army ants sets off. It is not an ambush: it is announced in advance, it says which side it comes in from and the top bar counts down. It enters at one edge, crosses in a straight line biting whatever stands in the way and leaves by the far side.",bloques:[{titulo:"The warning",texto:"Two hundred turns ahead the announcement fires with the heading \u2014 from the east, the west, the north or the south \u2014 and a countdown. With seasons on it only arrives in autumn and winter, which is when the field turns rough. While the front is crossing, no other creature spawns."},{titulo:"The front",texto:"It arrives formed in a line perpendicular to its heading and it ALWAYS advances: it does not sleep at night, it does not stop to wait and it does not need anyone to see it. It chases nobody \u2014 it bites whatever is left in its path \u2014 and each one is very frail and leaves little meat. What hurts is that there are many and they never swerve."},{titulo:"Counterplay",texto:"Three options, chosen with the warning in hand: shelter the colony, move whatever stands in the corridor out of the way, or set a wall of warriors against it. Everyone fights army ants just by standing next to them, but the HUNT order does not target them: against this you ATTACK or you hold."}],consejo:"When the warning fires, check the heading before the clock: moving a column aside costs a few turns of marching, and getting caught while carrying costs the whole column.",palabras:["army ants","marabunta","front","event","warning","threats"]}},[{etiqueta:e("Aviso","Warning"),valor:a("200 turnos","200 turns")},{etiqueta:e("El frente","The front"),valor:a("De 14 a 30 bichos","From 14 to 30 creatures")},{etiqueta:e("Cu\xE1ndo llega","When it arrives"),valor:a("Oto\xF1o e invierno","Autumn and winter")}],["mundo/fauna","mundo/invierno","hormiguero/defensa"]),...d?[o("tronco","idioma",{es:{titulo:"Los troncos a la deriva",subtitulo:"Madera flotante: el \xFAnico modo de que una obrera cambie de isla",resumen:"En el Caribe van a la deriva tres troncos: piezas de madera de dos casillas de ancho por seis de largo que recorren siempre la MISMA corriente, muy despacio, y se paran unos treinta o cuarenta turnos cada vez que tocan una orilla. Mientras est\xE1n parados son suelo: las hormigas suben con una orden normal, viajan encima y bajan en la isla siguiente. Nadie los dirige.",bloques:[{titulo:"La corriente",texto:"Es fija: la misma toda la partida, y va de la isla madre a cada una de las peque\xF1as y vuelta. No se sortea cada turno \u2014 se aprende. Saber por d\xF3nde pasa y cu\xE1ndo vuelve es la mitad del juego en el Caribe: no se coge el tronco que quieres, se coge el que pasa."},{titulo:"Subir y bajar",texto:"Solo mientras est\xE1 ATRACADO \u2014parado contra una orilla\u2014 sus casillas son suelo pisable. Le mandas ir, recolectar o atacar al otro lado y la hormiga sube sola. Navegando es agua: nadie planea un camino por el mar abierto, as\xED que la que no lleg\xF3 a tiempo se queda en la playa. Caben las que quepan (doce en un tronco de seis), suben cargadas con su miga, y dos colonias pueden compartirlo\u2026 y pelearse encima."},{titulo:"Lo que no se puede",texto:"Un tronco no se ataca \u2014es madera\u2014, no se cava y no se funda encima. Y no se dirige: es del mar, no tuyo. La reina puede subir, pero no lo necesita: para eso tiene alas."}],consejo:"Manda a la obrera cuando el tronco YA est\xE1 pegado a tu orilla, no cuando lo ves venir: si zarpa antes de que llegue, tu hormiga se queda mirando el agua treinta turnos. Y cuenta las que subes: lo que va en el tronco no defiende tu puerta.",palabras:["tronco","troncos","madera","deriva","corriente","balsa","isla","cruzar","caribe","mar"]},en:{titulo:"The drifting logs",subtitulo:"Floating wood: the only way a worker changes island",resumen:"Three logs drift through the Caribbean: pieces of wood two cells wide by six long that always follow the SAME current, very slowly, and stop for thirty or forty turns every time they touch a shore. While they are stopped they are ground: ants climb on with an ordinary order, ride, and get off on the next island. Nobody steers them.",bloques:[{titulo:"The current",texto:"It is fixed: the same all game, running from the mother island to each of the small ones and back. It is not drawn anew each turn \u2014 it is learned. Knowing where it passes and when it comes back is half the game in the Caribbean: you do not take the log you want, you take the one that passes."},{titulo:"Getting on and off",texto:"Only while it is MOORED \u2014 stopped against a shore \u2014 are its cells walkable ground. Order an ant to go, gather or attack on the other side and she climbs on by herself. Under way it is water: nobody plans a route across open sea, so whoever did not make it in time stays on the beach. As many fit as fit (twelve on a log of six), they climb on carrying their crumb, and two colonies can share one\u2026 and fight on it."},{titulo:"What you cannot do",texto:"A log is not attacked \u2014 it is wood \u2014 it is not dug and nothing is founded on it. And it is not steered: it belongs to the sea, not to you. A queen can climb on, but she does not need to: that is what wings are for."}],consejo:"Send the worker when the log is ALREADY against your shore, not when you see it coming: if it casts off before she arrives, your ant spends thirty turns looking at the water. And count the ones you send: what rides the log is not defending your door.",palabras:["log","logs","wood","drift","current","raft","island","cross","caribbean","sea"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Solo en el Caribe","Only in the Caribbean")},{etiqueta:e("Cu\xE1ntos","How many"),valor:a("3, de 2 \xD7 6 casillas","3, of 2 \xD7 6 cells")},{etiqueta:e("Lo que tarda","How slow"),valor:a("Una casilla cada 6 a 10 turnos","One cell every 6 to 10 turns")},{etiqueta:e("Atracado","Moored"),valor:a("De 30 a 40 turnos en cada orilla","30 to 40 turns at each shore")},{etiqueta:e("Se pisa","Walkable"),valor:a("Solo atracado","Only when moored")},{etiqueta:e("Se dirige","Steerable"),valor:a("No: es del mar","No: it belongs to the sea")}],["mundo/caribe","mundo/agua","mundo/sitio"])]:[],...l?[o("agua","idioma",{es:{titulo:"El agua del Fiordo",subtitulo:"Lagunas que se rodean y una isla a la que solo se vuela",resumen:"El Fiordo es el \xFAnico sitio con AGUA: tres lagunas de orilla irregular repartidas por el mapa, y en una de ellas una isla. Ninguna hormiga pisa el agua, no se funda en ella y no se cava en ella; pero se ve a trav\xE9s, y quien vuela la cruza. Las lagunas no cortan el mapa: todo el suelo sigue de una pieza y se rodean andando. La isla, no: a la isla solo se llega volando.",bloques:[{titulo:"Qu\xE9 es",texto:"Una casilla nueva, ni suelo ni roca. La roca se trepa perdiendo turnos; el agua no se cruza a pie de ninguna manera, ni las hormigas ni los bichos de suelo. En cambio no tapa nada: se ve al otro lado, y la avispa, la abeja y la lib\xE9lula vuelan por encima."},{titulo:"Las lagunas",texto:"Tres manchas de agua de unas cinco casillas de radio, cada una con su forma, donde el sorteo las ponga: nunca encima de un hormiguero de salida ni de su fald\xF3n, y siempre separadas entre s\xED, as\xED que el camino por tierra existe siempre. Una porteadora que va al otro lado de una laguna la rodea por la orilla."},{titulo:"La isla",texto:"Una de las lagunas lleva en medio un islote de suelo de dos casillas de radio, rodeado de agua por todos lados. Una reina en vuelo nupcial puede posarse y fundar ah\xED si cabe el hormiguero: nadie llega a pie a atacarla\u2026 y sus obreras tampoco salen. Es un refugio, no una f\xE1brica."}],consejo:"No mandes obreras a la isla: no hay camino y se quedan en la orilla. Si una reina rival funda en la isla, no la sitiar\xE1s a pie; y si fundas t\xFA, esa colonia vive de lo que cabe en el islote.",palabras:["agua","fiordo","laguna","lago","isla","islote","orilla","cruzar","volar"]},en:{titulo:"The Fjord\u2019s water",subtitulo:"Lakes you walk around, and an island you can only fly to",resumen:"The Fjord is the only place with WATER: three lakes with ragged shores scattered over the map, and an island in one of them. No ant walks on water, nothing is founded or dug in it; but you can see across it, and whatever flies crosses it. The lakes do not cut the map: all the ground stays in one piece and you walk around them. Not the island: the island can only be reached by flying.",bloques:[{titulo:"What it is",texto:"A new kind of cell, neither ground nor rock. Rock can be climbed at a cost in turns; water cannot be crossed on foot at all, not by ants nor by ground creatures. It hides nothing, though: you see the other side, and the wasp, the bee and the dragonfly fly over it."},{titulo:"The lakes",texto:"Three patches of water about five cells in radius, each with its own shape, wherever the draw puts them: never on a starting nest or its skirt, and always apart from each other, so a land route always exists. A carrier heading past a lake walks around its shore."},{titulo:"The island",texto:"One of the lakes has an islet of ground two cells in radius in the middle, surrounded by water on every side. A queen on her nuptial flight can land and found there if the nest fits: nobody reaches her on foot to attack\u2026 and her workers cannot leave either. It is a refuge, not a factory."}],consejo:"Do not send workers to the island: there is no path and they stop at the shore. If a rival queen founds on the island you will not besiege her on foot; and if you found there, that colony lives on what fits on the islet.",palabras:["water","fjord","lake","lagoon","island","islet","shore","cross","fly"]}},[{etiqueta:e("D\xF3nde","Where"),valor:a("Solo en el Fiordo","Only in the Fjord")},{etiqueta:e("Lagunas","Lakes"),valor:a("3, de radio 4 a 6","3, radius 4 to 6")},{etiqueta:e("La isla","The island"),valor:a("1, de radio 2, solo volando","1, radius 2, flying only")},{etiqueta:e("Qui\xE9n la cruza","Who crosses"),valor:a("La reina en vuelo, la avispa, la abeja y la lib\xE9lula","The queen in flight, the wasp, the bee and the dragonfly")},{etiqueta:e("La vista","Sight"),valor:a("Pasa: el agua no tapa","Passes: water hides nothing")}],["mundo/sitio","hormiguero/fundacion","fauna/libelula"])]:[]];export{c as TARJETAS_MUNDO};
